class Solution {

    public List<List<Integer>> combinationSum(
        int[] candidates,
        int target
    ) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(candidates, 0, target, new ArrayList<>(), res);
        return res;
    }

    private void dfs(
        int[] c,
        int i,
        int rem,
        List<Integer> path,
        List<List<Integer>> res
    ) {
        if (rem == 0) {
            res.add(new ArrayList<>(path));
            return;
        }
        if (i == c.length || rem < 0) return;
        path.add(c[i]); // pick c[i], stay at i (reuse allowed)
        dfs(c, i, rem - c[i], path, res);
        path.remove(path.size() - 1);
        dfs(c, i + 1, rem, path, res); // skip c[i] forever
    }
}

