class Solution {

    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(nums, 0, res);
        return res;
    }

    private void dfs(int[] nums, int k, List<List<Integer>> res) {
        if (k == nums.length) {
            List<Integer> perm = new ArrayList<>();
            for (int x : nums) perm.add(x);
            res.add(perm);
            return;
        }
        for (int i = k; i < nums.length; i++) {
            swap(nums, k, i); // put nums[i] into slot k
            dfs(nums, k + 1, res);
            swap(nums, k, i); // restore order for the next choice
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

