class Solution {

    public List<String> generateParenthesis(int n) {
        List<String> res = new ArrayList<>();
        gen(new char[2 * n], 0, res);
        return res;
    }

    private void gen(char[] cur, int pos, List<String> res) {
        if (pos == cur.length) {
            if (valid(cur)) res.add(new String(cur));
            return;
        }
        cur[pos] = '(';
        gen(cur, pos + 1, res);
        cur[pos] = ')';
        gen(cur, pos + 1, res);
    }

    private boolean valid(char[] s) {
        int bal = 0;
        for (char c : s) {
            bal += c == '(' ? 1 : -1;
            if (bal < 0) return false; // closed more than opened
        }
        return bal == 0;
    }
}

