            if (bal < 0) return false;
        }
        return bal === 0;
    };
    const gen = () => {
        if (cur.length === 2 * n) {
            if (valid()) res.push(cur.join(""));
            return;
        }
        for (const c of ["(", ")"]) {
            cur.push(c);
            gen();
            cur.pop();
        }
    };
    gen();
    return res;
};

