class Solution {

    public boolean exist(char[][] board, String word) {
        int m = board.length,
            n = board[0].length;
        boolean[][] vis = new boolean[m][n];
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            dfs(board, word, r, c, 0, vis)
        ) return true;
        return false;
    }

    private boolean dfs(
        char[][] b,
        String w,
        int r,
        int c,
        int k,
        boolean[][] vis
    ) {
        if (
            r < 0 || c < 0 || r >= b.length || c >= b[0].length
        ) return false;
        if (vis[r][c] || b[r][c] != w.charAt(k)) return false;
        if (k == w.length() - 1) return true;
        vis[r][c] = true; // block this cell on the current path
        boolean found =
            dfs(b, w, r + 1, c, k + 1, vis) ||
            dfs(b, w, r - 1, c, k + 1, vis) ||
            dfs(b, w, r, c + 1, k + 1, vis) ||
            dfs(b, w, r, c - 1, k + 1, vis);
        vis[r][c] = false; // unblock for other paths
        return found;
    }
}

