class Solution {

    public boolean exist(char[][] board, String word) {
        int m = board.length,
            n = board[0].length;
        if (word.length() > m * n) return false;
        int[] cnt = new int[128];
        for (char[] row : board) for (char ch : row) cnt[ch]++;
        for (char ch : word.toCharArray())
            if (--cnt[ch] < 0) return false; // not enough letters
        // Start from the rarer end to prune earlier
        int[] freq = new int[128];
        for (char[] row : board) for (char ch : row) freq[ch]++;
        if (
            freq[word.charAt(0)] > freq[word.charAt(word.length() - 1)]
        ) word = new StringBuilder(word).reverse().toString();
        char[] w = word.toCharArray();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            dfs(board, w, r, c, 0)
        ) return true;
        return false;
    }

    private boolean dfs(char[][] b, char[] w, int r, int c, int k) {
        if (
            r < 0 ||
            c < 0 ||
            r >= b.length ||
            c >= b[0].length ||
            b[r][c] != w[k]
        ) return false;
        if (k == w.length - 1) return true;
        char saved = b[r][c];
        b[r][c] = '#'; // mark visited in place
        boolean found =
            dfs(b, w, r + 1, c, k + 1) ||
            dfs(b, w, r - 1, c, k + 1) ||
            dfs(b, w, r, c + 1, k + 1) ||
            dfs(b, w, r, c - 1, k + 1);
        b[r][c] = saved; // restore
        return found;
    }
}

