        for (const ch of row) freq.set(ch, (freq.get(ch) || 0) + 1);
    const need = new Map();
    for (const ch of word) need.set(ch, (need.get(ch) || 0) + 1);
    for (const [ch, k] of need)
        if ((freq.get(ch) || 0) < k) return false; // not enough letters
    if (
        (freq.get(word[0]) || 0) >
        (freq.get(word[word.length - 1]) || 0)
    )
        word = [...word].reverse().join(""); // start from the rarer end
    const dfs = (r, c, k) => {
        if (
            r < 0 ||
            c < 0 ||
            r >= m ||
            c >= n ||
            board[r][c] !== word[k]
        )
            return false;
        if (k === word.length - 1) return true;
        const saved = board[r][c];
        board[r][c] = "#"; // mark in place
        const found =
            dfs(r + 1, c, k + 1) ||
            dfs(r - 1, c, k + 1) ||
            dfs(r, c + 1, k + 1) ||
            dfs(r, c - 1, k + 1);
        board[r][c] = saved; // restore
        return found;
    };
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++) if (dfs(r, c, 0)) return true;
    return false;
