        String digits,
        int k,
        StringBuilder sb,
        List<String> res
    ) {
        if (k == digits.length()) {
            res.add(sb.toString());
            return;
        }
        for (char ch : MAP[digits.charAt(k) - '0'].toCharArray()) {
            sb.append(ch); // choose a letter for position k
            dfs(digits, k + 1, sb, res);
            sb.deleteCharAt(sb.length() - 1); // un-choose
        }
    }
}

