class Solution {

    public List<List<String>> solveNQueens(int n) {
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        List<List<String>> res = new ArrayList<>();
        dfs(board, 0, res);
        return res;
    }

    private void dfs(char[][] b, int r, List<List<String>> res) {
        int n = b.length;
        if (r == n) {
            List<String> sol = new ArrayList<>();
            for (char[] row : b) sol.add(new String(row));
            res.add(sol);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (!safe(b, r, c)) continue;

            b[r][c] = 'Q';
            dfs(b, r + 1, res);
            b[r][c] = '.';
        }
    }

    private boolean safe(char[][] b, int r, int c) {
        int n = b.length;
        for (int i = r - 1; i >= 0; i--) if (
            b[i][c] == 'Q'
        ) return false; // column
        for (int i = r - 1, j = c - 1; i >= 0 && j >= 0; i--, j--) if (
            b[i][j] == 'Q'
        ) return false; // "\"
        for (int i = r - 1, j = c + 1; i >= 0 && j < n; i--, j++) if (
            b[i][j] == 'Q'
        ) return false; // "/"
        return true; // rows below are still empty
    }
}

