        for (int c = 0; c < n; c++) {
            int a = r - c + n - 1,
                s = r + c; // diagonal ids
            if (cols[c] || d1[a] || d2[s]) continue; // O(1) attack check
            cols[c] = d1[a] = d2[s] = true;
            b[r][c] = 'Q';
            dfs(r + 1, n, b, cols, d1, d2, res);
            b[r][c] = '.';
            cols[c] = d1[a] = d2[s] = false;
        }
    }
