class Solution {

    public void solveSudoku(char[][] board) {
        solve(board);
    }

    private boolean solve(char[][] b) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (b[r][c] != '.') continue;
                for (char d = '1'; d <= '9'; d++) {
                    if (!isValid(b, r, c, d)) continue;
                    b[r][c] = d; // choose
                    if (solve(b)) return true; // solved: stop, keep the digit
                    b[r][c] = '.'; // un-choose
                }
                return false; // no digit fits here: backtrack
            }
        }
        return true; // no empty cell left
    }

    private boolean isValid(char[][] b, int r, int c, char d) {
        for (int i = 0; i < 9; i++) {
            if (b[r][i] == d || b[i][c] == d) return false; // row / column
            if (
                b[3 * (r / 3) + i / 3][3 * (c / 3) + (i % 3)] == d
            ) return false; // 3x3 box
        }
        return true;
    }
}

