class Solution {

    private boolean[][] rowUsed = new boolean[9][10],
        colUsed = new boolean[9][10],
        boxUsed = new boolean[9][10];
    private List<int[]> empties = new ArrayList<>();

    public void solveSudoku(char[][] board) {
        for (int r = 0; r < 9; r++) for (int c = 0; c < 9; c++) {
            if (board[r][c] == '.') {
                empties.add(new int[] { r, c });
                continue;
            }
            int d = board[r][c] - '0';
            rowUsed[r][d] = colUsed[c][d] = boxUsed[
                (r / 3) * 3 + c / 3
            ][d] = true;
        }
        dfs(board, 0);
    }

    private boolean dfs(char[][] board, int idx) {
        if (idx == empties.size()) return true; // all cells filled
        int r = empties.get(idx)[0],
            c = empties.get(idx)[1],
            b = (r / 3) * 3 + c / 3;
        for (int d = 1; d <= 9; d++) {
            if (
                rowUsed[r][d] || colUsed[c][d] || boxUsed[b][d]
            ) continue; // O(1) check
            rowUsed[r][d] = colUsed[c][d] = boxUsed[b][d] = true;
            board[r][c] = (char) ('0' + d);
            if (dfs(board, idx + 1)) return true;
            board[r][c] = '.';
            rowUsed[r][d] = colUsed[c][d] = boxUsed[b][d] = false;
        }
        return false;
    }
}

