class Solution {

    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> res = new ArrayList<>();
        int top = 0,
            bottom = matrix.length - 1,
            left = 0,
            right = matrix[0].length - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) res.add(matrix[top][j]);
            top++;
            for (int i = top; i <= bottom; i++) res.add(
                matrix[i][right]
            );
            right--;
            if (top <= bottom) {
                // a row is still left
                for (int j = right; j >= left; j--) res.add(
                    matrix[bottom][j]
                );
                bottom--;
            }
            if (left <= right) {
                // a column is still left
                for (int i = bottom; i >= top; i--) res.add(
                    matrix[i][left]
                );
                left++;
            }
        }
        return res;
    }
}

