class Solution {

    public double myPow(double x, int n) {
        long N = n; // avoid overflow when n = Integer.MIN_VALUE
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        double res = 1;
        while (N > 0) {
            if ((N & 1) == 1) res *= x; // this bit of N is set: include current power
            x *= x; // x, x^2, x^4, x^8, ...
            N >>= 1;
        }
        return res;
    }
}

