class Solution {

    public String multiply(String num1, String num2) {
        int m = num1.length(),
            n = num2.length();
        int[] pos = new int[m + n];
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                int mul =
                    (num1.charAt(i) - '0') * (num2.charAt(j) - '0');
                int sum = mul + pos[i + j + 1]; // add to what's already there
                pos[i + j + 1] = sum % 10; // units digit stays
                pos[i + j] += sum / 10; // carry goes one place left
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d : pos)
            if (!(sb.length() == 0 && d == 0)) sb.append(d); // skip leading zeros
        return sb.length() == 0 ? "0" : sb.toString();
    }
}

