class DetectSquares {

    private Map<Integer, Integer> cnt = new HashMap<>();

    public DetectSquares() {}

    private int key(int x, int y) {
        return x * 1001 + y;
    } // coordinates are 0..1000

    public void add(int[] point) {
        cnt.merge(key(point[0], point[1]), 1, Integer::sum);
    }

    public int count(int[] point) {
        int qx = point[0],
            qy = point[1],
            res = 0;
        for (Map.Entry<Integer, Integer> e : cnt.entrySet()) {
            int px = e.getKey() / 1001,
                py = e.getKey() % 1001;
            if (
                px == qx || Math.abs(px - qx) != Math.abs(py - qy)
            ) continue; // need a real diagonal
            res +=
                e.getValue() *
                cnt.getOrDefault(key(qx, py), 0) *
                cnt.getOrDefault(key(px, qy), 0);
        }
        return res;
    }
}

