        let res = 0;
        for (const [k, c] of this.cnt) {
            const px = Math.floor(k / 1001),
                py = k % 1001;
            if (px === qx || Math.abs(px - qx) !== Math.abs(py - qy))
                continue;
            res += c * get(qx, py) * get(px, qy); // duplicates multiply
        }
        return res;
    }
