class Solution {

    public List<Integer> sieveOfEratosthenes(int n) {
        List<Integer> res = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            boolean prime = true;
            for (int d = 2; (long) d * d <= i; d++) {
                // a composite has a divisor <= sqrt(i)
                if (i % d == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) res.add(i);
        }
        return res;
    }
}

